/**
 * Test Case: End-to-End Shopping Journey
 *
 * Tags: @master @end-to-end @web
 *
 * Steps:
 * 1) Register a new customer with unique random data
 * 2) Log out
 * 3) Log in again with the new credentials
 * 4) Search for a known product, open it and add it to the cart
 * 5) Open the cart and verify product, quantity, price and total
 */

// Generated by GitHub Copilot - Nov-23-2026
import { test, expect } from '../../fixtures/pageFixtures';
import { RandomDataUtil } from '../../utils/dataGenerator';
import { Helper } from '../../utils/helper';

test('End-to-end shopping journey test @master @end-to-end @web', async ({
    homePage,
    registrationPage,
    loginPage,
    myAccountPage,
    logoutPage,
    searchResultsPage,
    productPage,
    shoppingCartPage,
}) => {
    // This single journey spans ~15 page loads on a public demo site, so it gets more than the 30s default.
    test.setTimeout(120 * 1000);

    // example.com is a reserved domain, so the site's confirmation e-mail never reaches a real inbox.
    const userData = {
        firstName: RandomDataUtil.getFirstName(),
        lastName: RandomDataUtil.getLastName(),
        email: `pw_${Date.now()}_${RandomDataUtil.getNumber()}@example.com`,
        telephone: RandomDataUtil.getPhoneNumber(),
        password: RandomDataUtil.getPassword(),
    };
    const { productName, productQuantity, totalPrice } = Helper.getProductDetails();

    await test.step('1) Register a new customer', async () => {
        await homePage.clickMyAccount();
        await homePage.clickRegister();
        expect(await registrationPage.isRegistrationPageExists()).toBeTruthy();
        await registrationPage.completeRegistration(userData);
        expect(await registrationPage.getConfirmationMsg()).toBe('Your Account Has Been Created!');
    });

    await test.step('2) Log out', async () => {
        await registrationPage.clickAccountContinue();
        expect(await myAccountPage.isMyAccountPageExists()).toBeTruthy();
        await myAccountPage.clickLogout();
        expect(await logoutPage.isLogoutPageExists()).toBeTruthy();
        await logoutPage.clickContinue();
        expect(await homePage.isHomePageExists()).toBeTruthy();
    });

    await test.step('3) Log in with the new credentials', async () => {
        await homePage.clickMyAccount();
        await homePage.clickLogin();
        expect(await loginPage.isLoginPageExists()).toBeTruthy();
        await loginPage.login(userData.email, userData.password);
        expect(await myAccountPage.isMyAccountPageExists()).toBeTruthy();
    });

    await test.step('4) Search for the product and add it to the cart', async () => {
        await homePage.searchProduct(productName);
        expect(await searchResultsPage.isProductExist(productName)).toBeTruthy();
        await searchResultsPage.selectProduct(productName);
        expect(await productPage.isProductPageExists()).toBeTruthy();
        expect(await productPage.getProductPrice()).toBe(totalPrice);
        await productPage.addProductToCart(productQuantity);
        expect(await productPage.getConfirmationMessage()).toContain(`Success: You have added ${productName} to your shopping cart!`);
    });

    await test.step('5) Verify product, quantity, price and total in the cart', async () => {
        await productPage.clickShoppingCart();
        expect(await shoppingCartPage.isShoppingCartPageExists()).toBeTruthy();
        expect(await shoppingCartPage.isProductInCart(productName)).toBeTruthy();
        expect(await shoppingCartPage.getProductQuantity(productName)).toBe(productQuantity);

        const unitPrice = await shoppingCartPage.getUnitPrice(productName);
        expect(unitPrice).toBe(totalPrice);

        // A new customer's cart holds only this product, so line total and cart total must equal price x quantity.
        const expectedTotal = Helper.convertPriceToNumber(unitPrice) * Number(productQuantity);
        expect(Helper.convertPriceToNumber(await shoppingCartPage.getProductTotal(productName))).toBe(expectedTotal);
        expect(Helper.convertPriceToNumber(await shoppingCartPage.getCartTotal())).toBe(expectedTotal);
    });

    console.log('✅ ✔️ End-to-end shopping journey completed successfully!');
});
